package com.payroll.service; import com.payroll.model.Payroll; import java.math.*; public final class PayrollCalculator { private PayrollCalculator(){} public static void calculate(Payroll p){ BigDecimal b=p.getEmployee().getBasicSalary(); BigDecimal hra=b.multiply(new BigDecimal("0.20")); BigDecimal da=b.multiply(new BigDecimal("0.10")); BigDecimal ta=b.multiply(new BigDecimal("0.05")); BigDecimal gross=b.add(hra).add(da).add(ta); BigDecimal pf=b.multiply(new BigDecimal("0.12")); BigDecimal tax=gross.compareTo(new BigDecimal("50000"))>0?gross.multiply(new BigDecimal("0.10")):gross.multiply(new BigDecimal("0.05")); p.setBasicSalary(b);p.setHra(hra);p.setDa(da);p.setTa(ta);p.setGrossSalary(gross);p.setPf(pf);p.setTax(tax);p.setNetSalary(gross.subtract(pf).subtract(tax).setScale(2,RoundingMode.HALF_UP)); } }